#include <vector>
#include <string>
#include <algorithm>
#include <queue>
#include <stack>
#include <deque>
#include <map>
#include <set>
#include <unordered_map>
#include <unordered_set>
#include <functional>
#include <numeric>
#include <sstream>
#include <iostream>
using namespace std;
int main(){int n;scanf("%d",&n);unordered_map<long long,int>c;
for(int i=0;i<n;++i){long long x;scanf("%lld",&x);++c[x];}
int best=0;
for(auto&kv:c)if(c.count(kv.first+1))best=max(best,kv.second+c[kv.first+1]);
printf("%d\n",best);return 0;}

